Bash(php artisan tinker --execute="
// Supprimer les notifications avec émojis
App\Models\Notification::where(''title'', ''LIKE'', ''%🎉%'')->delete();
App\Models\Notification::where(''title'', ''LIKE'', ''%:%'')->delete();

// Créer une nouvelle notification sans émoji
$user = App\Models\User::where(''name'', ''BEDE ABEL TEST'')->first();

if ($user) {
    $notif = App\Models\Notification::create([
        ''user_id'' => $user->id,
        ''type'' => App\Models\Notification::TYPE_LESSON_PUBLISHED,
        ''title'' => ''Nouveau cours disponible'',
        ''message'' => ''Le cours Introduction à Vue.js vient d\''être publié et est maintenant disponible pour vous'',
        ''data'' => [
            ''lesson_id'' => 999,
            ''matiere_id'' => 3,
            ''test'' => true
        ]
    ]);
    echo ''Notification créée ID: '' . $notif->id . '' pour '' . $user->name . PHP_EOL;
} else {
    echo ''Utilisateur non trouvé'' . PHP_EOL;
}
")
